"""
X Quant X dashboard -- final visual update (matches the team's real Variant A / B
color mockup: black background, mauve #B76E79 accent, pink #FFAEC9 alert cards).

This REPLACES the dashboard/ folder's 6 files with the final version. Safe to
run whether or not you ran update_dashboard_style.py before -- this script
does not depend on it and just overwrites with the final content.

Run this from the repo root (same folder as run_dashboard.py):
    python final_dashboard_update.py

Then:
    python -m pytest tests/ -q
    python run_dashboard.py
"""
import base64
import os

DASHBOARD_DIR = os.path.join("src", "investment_agent", "dashboard")

FILES_B64 = {
    "__init__.py": """IiIiWCBRdWFudCBYIG1vbml0b3JpbmcgZGFzaGJvYXJkIHBhY2thZ2UuCgpNb25pdG9yaW5nLW9ubHk6IG5vIG1vZHVsZSBpbiB0aGlzIHBhY2thZ2UgaW1wb3J0cyB0aGUgQWxwYWNhIFRyYWRpbmdDbGllbnQKZGlyZWN0bHkgb3Igc3VibWl0cyBvcmRlcnMuIFNlZSBkYXRhX2xvYWRlci5weSBhbmQgbGF5b3V0LnB5IGRvY3N0cmluZ3MuCiIiIgo=""",
    "app.py": """""",
    "charts.py": """""",
    "colors.py": """""",
    "data_loader.py": """""",
    "layout.py": """""",
}

def main():
    if not os.path.isdir(DASHBOARD_DIR):
        raise SystemExit(
            "Can't find " + DASHBOARD_DIR + " -- run this from the repo root "
            "(the same folder that has run_dashboard.py in it)."
        )
    os.makedirs(DASHBOARD_DIR, exist_ok=True)
    for fname, b64content in FILES_B64.items():
        content = base64.b64decode(b64content).decode("utf-8")
        path = os.path.join(DASHBOARD_DIR, fname)
        with open(path, "w", newline="\n", encoding="utf-8") as f:
            f.write(content)
        print("wrote", path)
    print("done -- now run: python -m pytest tests/ -q   then   python run_dashboard.py")

if __name__ == "__main__":
    main()
